INSERT INTO movies (id, title, original_title, duration, poster_url, backdrop_url, release_year, imdb_rating, type, language, description, video_file, video_url, original_srt, translated_srt, views) VALUES ('25e932e2-0688-4e73-944b-ae4ca235955c', 'The Holiday', NULL, '136 min', 'https://m.media-amazon.com/images/M/MV5BZmEwNDg0M2QtMDdiNy00YTliLTk4ZjctOThjZjczODVmMTdkXkEyXkFqcGc@._V1_SX300.jpg', NULL, 2006, 7, 'movie', 'English', 'ئاماندا لە شاری لۆس ئەنجلۆس دەژی و مۆنتاژکاری ترەیلەری فیلمەکانە. ئایریس لە شاری سوری دەژی و ڕۆژنامەنووسە. ئەو دووانە بڕیار دەدەن لە جەژنی کریسمسدا بۆ ماوەی دوو هەفتە خانوو بگۆڕنەوە - هەردووکیان هەوڵدەدەن ژیانی خۆشەویستی پڕ لە کێشەیان لەبیر بکەن، تاوەکو خۆشەویستی بە هەر شێوەیەک بێت دەیاندۆزێتەوە.', 'video.mp4', NULL, 'original.srt', 'translated.srt', 0) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title;
INSERT INTO movies (id, title, original_title, duration, poster_url, backdrop_url, release_year, imdb_rating, type, language, description, video_file, video_url, original_srt, translated_srt, views) VALUES ('ef708ceb-6b78-4d58-aa24-47d34a31f33d', 'The walking dead', NULL, '44 min', 'https://m.media-amazon.com/images/M/MV5BYWQwMGRhNGEtZTNhMy00MzVjLWJhMjItYjcwMDljMTkyNTg2XkEyXkFqcGc@._V1_SX300.jpg', NULL, 2010, 8.1, 'series', 'English', 'جێگری شەریف ڕیک گریمس لە کۆما لە خەو هەڵدەستێت بۆ ئەوەی بزانێت جیهان لە وێرانەدایە و دەبێت سەرکردایەتی کۆمەڵێک لە ڕزگاربووان بکات بۆ ئەوەی لە ژیاندا بمێننەوە.', NULL, NULL, NULL, NULL, 0) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title;
